#!/usr/bin/env python3
"""Generate the 32 legacy clothing ramps from repository-owned palette maps."""
from pathlib import Path
import re
import sys
from PIL import Image
ROOT=Path(__file__).resolve().parents[3]
source=(ROOT/'src/openrct2/drawing/Drawing.cpp').read_text().split('kPaletteToG1Offset[kPaletteTotalOffsets] = {',1)[1]
names=re.findall(r'SPR_PALETTE_([A-Z_]+)',source)[:32]
assert len(names)==32
lines=['/* SPDX-License-Identifier: GPL-3.0-only',
       ' * Generated by tools/guest_palette.py from OpenRCT2 palette PNGs.',
       ' * OpenRCT2 developers, 2014-2026. Do not edit by hand. */',
       'static const uint8_t guest_colour_ramps[32][12] = {']
for name in names:
    with Image.open(ROOT/'resources/palettes/map_base'/('palette_map_'+name.lower()+'.png')) as im:
        assert im.mode=='P' and im.size==(256,1)
        ramp=list(im.tobytes())[243:255]
    lines.append('    {'+','.join(map(str,ramp))+'}, /* '+name+' */')
lines.append('};')
text='\n'.join(lines)+'\n'
target=ROOT/'amiga/prototype/src/guest_palette.h'
if '--check' in sys.argv:
    assert target.read_text()==text,'Guest palette table needs regeneration'
    print('32 legacy clothing ramps match repository palette maps: PASS')
else:target.write_text(text)
